import{H as e,V as t,et as n,j as r}from"./chunks/framework.c0x6U8zS.js";var i=JSON.parse(`{"title":"SPF 数据包格式 V2（含 ORIGIN）","description":"","frontmatter":{},"headers":[],"relativePath":"common/spf-packet-v2.md","filePath":"common/spf-packet-v2.md","lastUpdated":1787587722000}`),a={name:`common/spf-packet-v2.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="spf-数据包格式-v2-含-origin" tabindex="-1">SPF 数据包格式 V2（含 ORIGIN） <a class="header-anchor" href="#spf-数据包格式-v2-含-origin" aria-label="Permalink to “SPF 数据包格式 V2（含 ORIGIN）”">​</a></h1><p>本文定义 <strong>SPF V2</strong> 的<strong>通用帧封装</strong>。与 <a href="./spf-packet.html">SPF 数据包格式（V1）</a> 相比，<strong>仅在 OP 与 VALUE 之间增加 1 字节 ORIGIN</strong>；帧头、OP 含义、异或校验、粘包解析规则与 V1 相同。</p><p><strong>V2 适用 AHE02 / AHE04</strong> 网关与主板之间的 UART（含 ORIGIN）。<strong>AHE01</strong> 仍用 <a href="./spf-packet.html">SPF 数据包格式（V1）</a>（无 ORIGIN）。<strong>AHE03</strong> 为外包产品，不走标准 SPF 串口协议，见 <a href="/ahs-docs-page/products/ahe03/">AHE03 产品概述</a>。</p><p><strong>CMD 取值、VALUE 含义、谁先发谁后回</strong> 不在本文。AHE04 命令字典见 <a href="/ahs-docs-page/products/ahe04/spf-protocol.html">AHE04 STM32 ↔ ESP32 串口协议</a>。AHE02 命令字典待产品文档补充。</p><p>APP ↔ 设备空中包见 <a href="./ble-packet.html">BLE 数据包格式</a>。SPF 与 BLE 是两套独立封装，不要混用字段名。</p><h2 id="与-v1-的差异-摘要" tabindex="-1">与 V1 的差异（摘要） <a class="header-anchor" href="#与-v1-的差异-摘要" aria-label="Permalink to “与 V1 的差异（摘要）”">​</a></h2><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>项目</th><th>V1</th><th>V2</th></tr></thead><tbody><tr><td>OP 之后</td><td>直接 VALUE</td><td><strong>ORIGIN</strong> 再 VALUE</td></tr><tr><td>LENGTH</td><td><code>value_len + 3</code></td><td><strong><code>value_len + 4</code></strong></td></tr><tr><td>最短帧</td><td>7 字节</td><td><strong>8 字节</strong></td></tr></tbody></table></div><p>OP、CHECK 计算范围、粘包解析等细节见 <a href="./spf-packet.html">SPF 数据包格式（V1）</a> 对应章节；组帧时在 OP 后插入 ORIGIN 即可。</p><h2 id="_1-帧格式" tabindex="-1">1. 帧格式 <a class="header-anchor" href="#_1-帧格式" aria-label="Permalink to “1. 帧格式”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌────────┬────────┬─────────┬──────┬──────┬─────────┬────────────┬───────┐</span></span>
<span class="line"><span>│ HEAD1  │ HEAD2  │ LENGTH  │ CMD  │ OP   │ ORIGIN  │ VALUE      │ CHECK │</span></span>
<span class="line"><span>│ 1 字节 │ 1 字节 │ 2 字节  │ 1字节 │ 1字节 │ 1 字节  │ n 字节     │ 1 字节 │</span></span>
<span class="line"><span>└────────┴────────┴─────────┴──────┴──────┴─────────┴────────────┴───────┘</span></span></code></pre></div><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>HEAD1 / HEAD2</td><td>各 1 字节</td><td>固定 <code>0x5A 0xA5</code></td></tr><tr><td>LENGTH</td><td>2 字节</td><td><strong>大端</strong>。等于 <code>CMD + OP + ORIGIN + VALUE + CHECK</code> 的字节数，即 <strong><code>4 + n</code></strong></td></tr><tr><td>CMD</td><td>1 字节</td><td>命令码，见各产品 <a href="/ahs-docs-page/products/ahe04/spf-protocol.html">spf-protocol</a></td></tr><tr><td>OP</td><td>1 字节</td><td>操作码，含义同 <a href="./spf-packet.html#_4-操作码op">V1 §4</a></td></tr><tr><td><strong>ORIGIN</strong></td><td><strong>1 字节</strong></td><td><strong>发起者</strong>，见 <a href="#_2-origin-发起者">§2</a></td></tr><tr><td>VALUE</td><td>n 字节</td><td>业务载荷；<code>n = LENGTH − 4</code>，可为 0</td></tr><tr><td>CHECK</td><td>1 字节</td><td>从 HEAD1 到 VALUE 末字节异或，规则同 <a href="./spf-packet.html#_5-异或校验check">V1 §5</a></td></tr></tbody></table></div><p>关系：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LENGTH     = 4 + value_len</span></span>
<span class="line"><span>总帧长     = LENGTH + 4  = value_len + 8</span></span>
<span class="line"><span>最短帧     = 8 字节（VALUE 为空）</span></span></code></pre></div><h2 id="_2-origin-发起者" tabindex="-1">2. ORIGIN 发起者 <a class="header-anchor" href="#_2-origin-发起者" aria-label="Permalink to “2. ORIGIN 发起者”">​</a></h2><p>ORIGIN 标记<strong>本条 SPF 读写是谁发起的</strong>，便于网关把 STM32 应答路由回 BLE / MQTT / HTTP 等上层。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td><code>0x00</code></td><td>STM32 主动上报 / 无上层发起者（如 NOTIFY <code>0xC0</code>）</td></tr><tr><td><code>0x01</code></td><td>手机 APP（经 BLE 透传时使用）</td></tr><tr><td><code>0x02</code></td><td>MQTT / MQTTS</td></tr><tr><td><code>0x03</code></td><td>HTTP / HTTPS</td></tr><tr><td><code>0x04</code></td><td>ESP 本地（如读版本、上报蓝牙连接状态）</td></tr></tbody></table></div><p>约定：</p><ul><li>APP 经 BLE 下发的读写，ESP32 组 SPF 时 <strong>ORIGIN = <code>0x01</code></strong>。</li><li>STM32 回写应答 / 读应答时，<strong>须原样回写</strong>请求帧中的 ORIGIN。</li><li>APP 的 BLE 包<strong>不含</strong> ORIGIN 字段；仅 UART SPF 层有。</li></ul><h2 id="_3-通讯示例" tabindex="-1">3. 通讯示例 <a class="header-anchor" href="#_3-通讯示例" aria-label="Permalink to “3. 通讯示例”">​</a></h2><p>以下只演示 V2 封装。CMD <code>0xA1</code> 在 AHE04 上表示加热，完整含义见 <a href="/ahs-docs-page/products/ahe04/spf-protocol.html">AHE04 STM32 ↔ ESP32 串口协议</a>。</p><h3 id="_3-1-app-经-ble-写加热-origin-ble" tabindex="-1">3.1 APP 经 BLE 写加热（ORIGIN = BLE） <a class="header-anchor" href="#_3-1-app-经-ble-写加热-origin-ble" aria-label="Permalink to “3.1 APP 经 BLE 写加热（ORIGIN = BLE）”">​</a></h3><p>VALUE：<code>01 00 1E 02</code>（开、30 分钟、中档），ORIGIN = <code>0x01</code>。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ESP32 → STM32：5A A5 00 08 A1 00 01 01 00 1E 02 CHECK</span></span>
<span class="line"><span>                      │     │  │  │  └─ VALUE 4 字节</span></span>
<span class="line"><span>                      │     │  │  └─ ORIGIN=0x01</span></span>
<span class="line"><span>                      │     │  └─ OP 写</span></span>
<span class="line"><span>                      │     └─ CMD 加热</span></span>
<span class="line"><span>                      └─ LENGTH=8（4+4）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>STM32 → ESP32：5A A5 00 05 A1 01 01 01 CHECK</span></span>
<span class="line"><span>                        │  │  │  └─ 成功 0x01</span></span>
<span class="line"><span>                        │  │  └─ ORIGIN 回显 0x01</span></span>
<span class="line"><span>                        │  └─ OP 写应答</span></span>
<span class="line"><span>                        └─ LENGTH=5</span></span></code></pre></div><h3 id="_3-2-读命令-无-value" tabindex="-1">3.2 读命令（无 VALUE） <a class="header-anchor" href="#_3-2-读命令-无-value" aria-label="Permalink to “3.2 读命令（无 VALUE）”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ESP32：5A A5 00 04 A1 02 01 CHECK     ORIGIN=0x01，无 VALUE</span></span>
<span class="line"><span>STM32：5A A5 00 08 A1 03 01 … CHECK  读应答 VALUE + ORIGIN 回显</span></span></code></pre></div><h3 id="_3-3-stm32-主动通知" tabindex="-1">3.3 STM32 主动通知 <a class="header-anchor" href="#_3-3-stm32-主动通知" aria-label="Permalink to “3.3 STM32 主动通知”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STM32：5A A5 00 12 C0 FF 00 （14 字节 VALUE） CHECK</span></span>
<span class="line"><span>                    │  │  └─ ORIGIN=0x00</span></span>
<span class="line"><span>                    │  └─ OP 通知</span></span>
<span class="line"><span>                    └─ CMD 实时数据</span></span>
<span class="line"><span>LENGTH = 4 + 14 = 0x0012</span></span></code></pre></div><h2 id="_4-重要说明" tabindex="-1">4. 重要说明 <a class="header-anchor" href="#_4-重要说明" aria-label="Permalink to “4. 重要说明”">​</a></h2><ol><li>V2 <strong>一帧一条命令</strong>，无 BLE 式分包；超长 VALUE 由业务拆多帧。</li><li>LENGTH 含 CMD、OP、<strong>ORIGIN</strong>、VALUE、CHECK，<strong>不含</strong>两字节帧头。</li><li>必须校验 CHECK；失败丢帧。</li><li>多字节一律大端。</li><li>具体 CMD / VALUE 见各产品 spf-protocol（如 <a href="/ahs-docs-page/products/ahe04/spf-protocol.html">AHE04</a>、AHE02 待补充）；不要把 BLE 的 <code>cmd</code> 直接填进 SPF 的 CMD。</li></ol>`,29)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};